/* ---------- Buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;          /* 44px */
  padding: 0.65rem 1.4rem;
  border-radius: var(--radius-btn);
  font-weight: 600;
  font-size: 1rem;
  line-height: 1.25;
  text-align: center;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms cubic-bezier(0.22, 1, 0.36, 1),
              transform 100ms cubic-bezier(0.22, 1, 0.36, 1);
}
.btn:active { transform: translateY(1px) scale(0.98); }

.btn--cobalt { background: var(--cobalt); color: var(--on-dark); }
.btn--ink    { background: var(--ink);    color: var(--on-dark); }
.btn--light  { background: var(--on-dark); color: var(--cobalt); }

@media (hover: hover) {
  .btn--cobalt:hover { background: oklch(0.38 0.14 262); }
  .btn--ink:hover    { background: oklch(0.32 0.03 50); }
  .btn--light:hover  { background: oklch(0.9 0.02 250); }
}

@media (prefers-reduced-motion: reduce) {
  .btn { transition: background-color 120ms linear; }
  .btn:active { transform: none; }
}

.textlink {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  font-weight: 600;
}

/* ---------- The rim (header): glazed, drips hang into the hero ---------- */

.rim {
  --ring: var(--on-dark);
  position: relative;
  background: var(--cobalt);
  color: var(--on-dark);
}
.rim::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 100%;
  height: 28px;
  background: var(--cobalt);
  -webkit-mask: var(--drip) repeat-x 0 0 / 240px 28px;
          mask: var(--drip) repeat-x 0 0 / 240px 28px;
  pointer-events: none;
}

.rim__inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1.5rem;
  padding-block: 0.75rem;
}

.wordmark {
  font-family: var(--font-display);
  font-size: var(--step-1);
  color: inherit;
  text-decoration: none;
  margin-right: auto;
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
}

.nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0 0.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.nav a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  padding-inline: 0.75rem;
