  transition: background-color 180ms cubic-bezier(0.22, 1, 0.36, 1),
              transform 100ms cubic-bezier(0.22, 1, 0.36, 1);
}
.btn:active { transform: translateY(1px) scale(0.98); }

.btn--cobalt { background: var(--cobalt); color: var(--on-dark); }
.btn--ink    { background: var(--ink);    color: var(--on-dark); }
.btn--light  { background: var(--on-dark); color: var(--cobalt); }

@media (hover: hover) {
  .btn--cobalt:hover { background: oklch(0.38 0.14 262); }
  .btn--ink:hover    { background: oklch(0.32 0.03 50); }
  .btn--light:hover  { background: oklch(0.9 0.02 250); }
}

@media (prefers-reduced-motion: reduce) {
  .btn { transition: background-color 120ms linear; }
  .btn:active { transform: none; }
}

.textlink {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  font-weight: 600;
}

/* ---------- The rim (header): glazed, drips hang into the hero ---------- */

.rim {
  --ring: var(--on-dark);
  position: relative;
  background: var(--cobalt);
  color: var(--on-dark);
}
.rim::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 100%;
  height: 28px;
  background: var(--cobalt);
  -webkit-mask: var(--drip) repeat-x 0 0 / 240px 28px;
          mask: var(--drip) repeat-x 0 0 / 240px 28px;
  pointer-events: none;
}

.rim__inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1.5rem;
  padding-block: 0.75rem;
}

.wordmark {
  font-family: var(--font-display);
  font-size: var(--step-1);
  color: inherit;
  text-decoration: none;
  margin-right: auto;
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
}

.nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0 0.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.nav a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  padding-inline: 0.75rem;
  color: var(--on-dark);
  text-decoration: none;
  font-weight: 600;
}
@media (hover: hover) {
  .nav a:hover { text-decoration: underline; text-decoration-thickness: 2px; }
}

@media (max-width: 40rem) {
  .rim__inner { padding-block: 0.5rem 0.75rem; }
  .rim nav { order: 3; width: 100%; }
  .nav { margin-inline: -0.75rem; }
  .rim__cta { padding-inline: 1rem; }
}

/* ---------- Hero ---------- */

.hero {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  align-items: center;
  gap: 3rem 4rem;
  padding-block: 5rem 4.5rem;
}

.hero h1 { font-size: var(--step-4); max-width: 12ch; }

.lede {
  margin-top: 1.5rem;
  max-width: 34rem;
  font-size: 1.1875rem;
  color: var(--muted);
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem 1.5rem;
  margin-top: 2rem;
}

.hero__photo { margin: 0; }

@media (max-width: 52rem) {
  .hero { grid-template-columns: 1fr; padding-block: 4rem 3rem; }
}

/* ---------- Photo placeholders ---------- */

/* Throwing rings: the spiral ridges a wheel leaves in the clay */
.ph {
  display: grid;
  place-items: end start;
  aspect-ratio: 4 / 3;
  padding: 1rem;
  border-radius: 0.5rem;
  background:
    repeating-radial-gradient(circle at 70% 60%,
      oklch(0.83 0.035 75) 0 3px,
      oklch(0.86 0.035 75) 3px 9px);
}
.ph span {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--muted);
  background: var(--bg);
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
}
.ph--tall { aspect-ratio: 4 / 5; }
.ph--wide { aspect-ratio: 16 / 10; }

figure { margin: 0; }
figcaption {
  margin-top: 0.6rem;
  font-size: 0.9375rem;
  color: var(--muted);
}

/* ---------- Section heads ---------- */

.section-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
  gap: 1rem 4rem;
  align-items: end;
  margin-bottom: 3rem;
}
.section-head h2 { font-size: var(--step-3); }
.section-head p { color: var(--muted); max-width: 38rem; }

@media (max-width: 52rem) {
  .section-head { grid-template-columns: 1fr; margin-bottom: 2rem; }
}

/* ---------- Workshops: test tiles ---------- */

.workshops {
  background: var(--surface);
  padding-block: 5.5rem 5rem;
}

.tiles {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr 1.25fr 1fr;
  gap: 1.75rem;
  align-items: start;
}

/* tiles hang on the wall at slightly different heights */
.tile:not(.tile--flagship) { margin-top: 2.5rem; }

.tile {
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-tile) var(--radius-tile) 0.5rem 0.5rem;
  background: var(--clay);
  box-shadow: 0 1px 0 oklch(0.7 0.03 75), 0 10px 24px -14px oklch(0.24 0.02 50 / 0.45);
  overflow: hidden;
}

.tile__glaze {
  position: relative;
  padding: 3.25rem 1.5rem 1.5rem;
  background: var(--glaze);
  color: var(--on-glaze);
}
/* the punched hanging hole */
.tile__glaze::before {
  content: "";
  position: absolute;
  top: 1rem;
  left: 50%;
  width: 1rem;
  height: 1rem;
  margin-left: -0.5rem;
  border-radius: 50%;
  background: var(--surface);
  box-shadow: inset 0 2px 3px oklch(0.24 0.02 50 / 0.35);
}
/* the glaze running down onto the raw clay */
.tile__glaze::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 100%;
  height: 28px;
  background: var(--glaze);
  -webkit-mask: var(--drip) repeat-x var(--drip-x, 0) 0 / 240px 28px;
          mask: var(--drip) repeat-x var(--drip-x, 0) 0 / 240px 28px;
  pointer-events: none;
}

.tile h3 { font-size: var(--step-2); }

.price {
  margin-top: 0.5rem;
  font-family: var(--font-display);
  font-size: var(--step-2);
  font-variant-numeric: tabular-nums;
}
.price span {
  font-family: var(--font-body);
  font-size: 1rem;
  color: var(--on-glaze-muted);
}

.tile__note {
  margin-top: 0.25rem;
  font-weight: 600;
  color: var(--on-glaze-muted);
}

.tile__foot {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  flex: 1;
  padding: 2.75rem 1.5rem 1.5rem;   /* top clears the drips */
}

.facts {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.5rem;
}
.facts li {
  padding-left: 1.1rem;
  position: relative;
}
.facts li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.65em;
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: var(--ink);
}

.tile .btn { align-self: flex-start; }

.tile--celadon { --glaze: var(--celadon); --on-glaze: var(--ink); --on-glaze-muted: var(--ink); --drip-x: 40px; }
.tile--cobalt  { --glaze: var(--cobalt);  --on-glaze: var(--on-dark); --on-glaze-muted: var(--on-dark-muted); --drip-x: -90px; }
.tile--tenmoku { --glaze: var(--tenmoku); --on-glaze: var(--on-dark); --on-glaze-muted: var(--on-dark-muted); --drip-x: 150px; }

.tile--flagship .tile__glaze { padding-block: 3.75rem 2rem; }
.tile--flagship h3 { font-size: var(--step-3); }

.book-note {
  margin-top: 3rem;
  max-width: 44rem;
  color: var(--muted);
}

@media (max-width: 60rem) {
  .tiles { grid-template-columns: 1fr; max-width: 30rem; }
  .tile:not(.tile--flagship) { margin-top: 0; }
}

/* ---------- Studio gallery ---------- */

.studio { padding-block: 5.5rem 6rem; }

.gallery {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 2rem 1.5rem;
}
.gallery__big { grid-column: 1; grid-row: span 2; display: flex; flex-direction: column; }
.gallery__big .ph { aspect-ratio: auto; flex: 1; min-height: 16rem; }
.gallery figure:nth-child(4) { grid-column: 2 / span 2; }
.gallery figure:nth-child(4) .ph { aspect-ratio: 21 / 9; }

@media (max-width: 52rem) {
  .gallery { grid-template-columns: 1fr 1fr; }
  .gallery__big { grid-column: 1 / -1; grid-row: auto; }
  .gallery__big .ph { aspect-ratio: 16 / 10; height: auto; min-height: 0; }
  .gallery figure:nth-child(4) { grid-column: 1 / -1; }
}
@media (max-width: 30rem) {
  .gallery { grid-template-columns: 1fr; }
  .gallery figure:nth-child(4) .ph { aspect-ratio: 4 / 3; }
}

/* ---------- The foot (footer): raw clay with the maker's stamp ---------- */

.foot {
  background: var(--clay);
  color: var(--ink);
  padding-block: 4rem 2rem;
}

.foot__inner {
  display: grid;
  grid-template-columns: auto 1fr 1fr;
  gap: 2.5rem 4rem;
  align-items: start;
}

.foot h2 { font-size: var(--step-2); margin-bottom: 1rem; }
.foot h3 { font-size: var(--step-0); font-family: var(--font-body); font-weight: 600; }
.foot h3 + p { margin-bottom: 1.25rem; }
.foot address { font-style: normal; }
.foot a { display: inline-block; padding-block: 0.3rem; }

/* impressed chop mark, the way a potter signs the foot */
.stamp {
  display: grid;
  place-items: center;
  width: 5.5rem;
  height: 5.5rem;
  border-radius: 50%;
  border: 2px solid oklch(0.62 0.04 70);
  font-family: var(--font-display);
  font-size: 1.25rem;
  color: oklch(0.5 0.04 70);
  box-shadow: inset 0 2px 4px oklch(0.24 0.02 50 / 0.25), 0 1px 0 oklch(0.92 0.03 75);
  transform: rotate(-8deg);
}

.foot__small {
  margin-top: 3rem;
  font-size: 0.875rem;
  color: var(--muted);
}

@media (max-width: 52rem) {
  .foot__inner { grid-template-columns: 1fr 1fr; }
  .stamp { grid-column: 1 / -1; }
}
@media (max-width: 30rem) {
  .foot__inner { grid-template-columns: 1fr; }
}

