const { chromium } = require('playwright');
const path = require('path');
const url = 'file:///' + path.resolve(__dirname, 'index.html').replace(/\\/g, '/');
const out = path.resolve(__dirname, '.shots');
require('fs').mkdirSync(out, { recursive: true });

const overflow = () => [...document.querySelectorAll('body *')]
  .filter(el => el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflow === 'visible')
  .map(el => `${el.tagName}.${el.className}`)
  .concat(document.documentElement.scrollWidth > innerWidth ? ['PAGE ' + document.documentElement.scrollWidth] : []);

(async () => {
  const browser = await chromium.launch();
  for (const [w, h, rm] of [[320, 700], [640, 320], [768, 1000], [1280, 900], [1920, 1080], [390, 800, 'reduce']]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, reducedMotion: rm || 'no-preference' });
    const page = await ctx.newPage();
    const errs = [], failed = [];
    page.on('console', m => m.type() === 'error' && errs.push(m.text()));
    page.on('requestfailed', r => failed.push(r.url()));
    const responses = [];
    page.on('response', r => responses.push(r.status() + ' ' + r.url().slice(0, 70)));
    await page.goto(url, { waitUntil: 'networkidle' });
    await page.evaluate(() => document.fonts.ready);
    const fonts = await page.evaluate(() => ({ young: document.fonts.check('16px "Young Serif"'), fig: document.fonts.check('600 16px "Figtree"') }));
    const of = await page.evaluate(overflow);
    const small = await page.evaluate(() => [...document.querySelectorAll('a[href],button')]
      .map(el => [el, el.getBoundingClientRect()]).filter(([el, r]) => r.width && (r.width < 24 || r.height < 24) && el.className !== 'skip')
      .map(([el, r]) => `${el.textContent.trim().slice(0, 20)} ${r.width|0}x${r.height|0}`));
    await page.screenshot({ path: `${out}/w${w}${rm ? '-rm' : ''}.png`, fullPage: true });
    console.log(`\n== ${w}x${h} ${rm || ''}`, { fonts, overflow: of, small, errs, failed });
    if (w === 1280) {
      console.log('responses', responses);
      // 200% text zoom
      await page.evaluate(() => document.documentElement.style.fontSize = '200%');
      console.log('200% text overflow', await page.evaluate(overflow));
      await page.screenshot({ path: `${out}/w1280-text200.png`, fullPage: true });
      await page.evaluate(() => document.documentElement.style.fontSize = '');
      // keyboard walk
      const stops = [];
      for (let i = 0; i < 22; i++) {
        await page.keyboard.press('Tab');
        stops.push(await page.evaluate(() => {
          const a = document.activeElement, r = a.getBoundingClientRect(), cs = getComputedStyle(a);
          const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
          return `${a.textContent.trim().slice(0, 28)} | outline ${cs.outlineStyle} ${cs.outlineColor} | visible ${a.contains(hit) || hit === a}`;
        }));
      }
      console.log(stops.join('\n'));
      await page.keyboard.press('Shift+Tab');
      // focused-state screenshot of a tile button
      await page.focus('.tile--cobalt .btn');
      await page.screenshot({ path: `${out}/focus-tile.png`, clip: await page.evaluate(() => { const r = document.querySelector('.tile--cobalt').getBoundingClientRect(); return { x: r.x - 10, y: r.y + scrollY - 10, width: r.width + 20, height: r.height + 20 }; }) }).catch(e => console.log('clip', e.message));
      await page.focus('.rim .nav a');
      await page.screenshot({ path: `${out}/focus-nav.png`, clip: { x: 0, y: 0, width: 1280, height: 140 } });
    }
    await ctx.close();
  }
  await browser.close();
})();

